'use strict';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bookmark:'M6 3h12v18l-6-4-6 4z',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',command:'M9 7V5a2 2 0 1 0-2 2h10a2 2 0 1 0-2-2v14a2 2 0 1 0 2-2H7a2 2 0 1 0 2 2V7',sliders:'M4 6h4m4 0h8 M4 18h8m4 0h4 M8 3v6 M16 15v6 M4 12h12m4 0h0 M16 9v6',table:'M3 3h18v18H3z M3 9h18 M9 3v18 M3 15h18',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',library:'M4 3v18 M9 3v18 M14 3l6 18',arrow:'M5 12h14 m-5-5 5 5-5 5',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',play:'m8 5 11 7-11 7z',x:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4 10-10',plus:'M12 5v14 M5 12h14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',folder:'M3 6h7l2 3h9v11H3z',copy:'M8 8h13v13H8z M16 8V3H3v13h5'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups={all:'すべてのパーツ',saved:'お気に入り',overlay:'重ねて表示',navigation:'操作・移動',input:'入力・選択',information:'情報・状態'};
const catalog=window.PARTS_CATALOG;
const parts=catalog.parts;
const examples=catalog.examples;
function miniature(id){
const bar='<div class="mini-bar"><i></i><i></i><i></i></div>';
const line='<div class="mini-line"></div><div class="mini-line short"></div><div class="mini-line medium"></div>';
switch(id){
case'modal':return `<div class="mini modal-canvas"><div class="mini-window background-window">${bar}${line}${line}</div><div class="modal-specimen"><div class="mini-icon">${icon('folder')}</div><div class="mini-title">Create a collection</div><div class="mini-copy">Give your next idea a place to live.</div><div class="mini-actions"><span class="mini-btn outline">Cancel</span><span class="mini-btn">Create</span></div></div></div>`;
case'drawer':return `<div class="mini mini-window drawer-canvas">${bar}<div class="drawer-underlay"><div class="mini-title">Reservations</div>${line}${line}</div><div class="drawer-specimen"><div class="mini-row"><span class="mini-title">Reservation</span><span>×</span></div><div class="mini-copy">GUEST</div><div style="font-size:9px">Aoi Tanaka</div><div class="mini-copy">CHECK-IN</div><div style="font-size:9px">Sep 18, 2026</div><span class="mini-btn">View details</span></div></div>`;
case'popover':return `<div class="mini popover-canvas"><div class="popover-anchor">${icon('sliders')} Display</div><div class="popover-specimen"><div class="mini-title">Display settings</div><div class="mini-row">Show preview <span class="mini-switch"></span></div><div class="mini-row">Show labels <span class="mini-switch"></span></div></div></div>`;
case'command':return `<div class="mini command-specimen"><div class="mini-search">${icon('search')}Type a command…<kbd>esc</kbd></div><div class="command-caption">SUGGESTED</div><div class="command-row selected">${icon('plus')}Create collection<small>↵</small></div><div class="command-row">${icon('grid')}Browse components<small>G B</small></div><div class="command-row">${icon('settings')}Settings<small>G S</small></div></div>`;
case'table':return `<div class="mini table-specimen"><div class="table-top"><span class="mini-title">Reservations</span><span class="mini-copy">3 results</span></div><table class="mini-table"><thead><tr><th></th><th>Guest</th><th>Status</th><th>Amount</th></tr></thead><tbody>${[['Aoi Tanaka','¥24,000'],['Yuki Sato','¥18,500'],['Ren Suzuki','¥32,000']].map(r=>`<tr><td><span class="mini-checkbox"></span></td><td>${r[0]}</td><td><span class="mini-badge">Confirmed</span></td><td>${r[1]}</td></tr>`).join('')}</tbody></table></div>`;
case'tabs':return `<div class="mini tabs-specimen"><div class="mini-title">Project settings</div><div class="mini-tabs"><span class="active">General</span><span>Members</span><span>Activity</span></div><div class="mini-tab-content"><div class="mini-avatar">P</div><div><div class="mini-title">Parts library</div><div class="mini-copy">Your workspace, organized.</div></div></div></div>`;
case'toast':return `<div class="mini toast-canvas"><div class="toast-specimen"><span class="toast-check">${icon('check')}</span><div><div class="mini-title">Changes saved</div><div class="mini-copy">Your collection is up to date.</div></div><span>×</span></div><div class="toast-hint">A LITTLE UPDATE. KEEP GOING.</div></div>`;
case'date':return `<div class="mini date-specimen"><div class="date-head"><span>‹</span><b>September 2026</b><span>›</span></div><div class="date-grid">${['M','T','W','T','F','S','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}<span class="dim">31</span>${Array.from({length:30},(_,i)=>`<span class="${i===17?'start':i===21?'end':i>17&&i<21?'range':''}">${i+1}</span>`).join('')}<span class="dim">1</span><span class="dim">2</span><span class="dim">3</span><span class="dim">4</span></div><div class="date-caption">SEP 18 – SEP 22 · 4 NIGHTS</div></div>`;
}}
let storageAvailable=true;
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{storageAvailable=false;return fallback}}
let saved=readLocal('parts.favorites.v1',[]);if(!Array.isArray(saved))saved=[];saved=new Set(saved.filter(id=>parts.some(p=>p.id===id)));
let notes=readLocal('parts.notes.v1',{});if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};
let view=readLocal('parts.view.v1','grid');if(!['grid','list'].includes(view))view='grid';
let filter='all',currentId=null,noticeTimer;
const grid=document.querySelector('#parts-grid'),search=document.querySelector('#search'),detail=document.querySelector('#detail');
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageAvailable=false;return false}}
function notify(message){clearTimeout(noticeTimer);const n=document.querySelector('#notification');n.textContent=message;n.hidden=false;noticeTimer=setTimeout(()=>n.hidden=true,3500)}
function filteredParts(){const terms=search.value.normalize('NFKC').toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);let results=parts.filter(p=>(filter==='all'||filter==='saved'&&saved.has(p.id)||p.category===filter)&&terms.every(term=>[p.name,p.ja,p.summary,p.description,p.use,...p.aliases,...examples.filter(e=>e.partId===p.id).flatMap(e=>[e.system,e.title,e.summary,...e.features])].join(' ').normalize('NFKC').toLocaleLowerCase().includes(term)));if(document.querySelector('#sort').value==='name')results.sort((a,b)=>a.name.localeCompare(b.name));return results}
function render(){const results=filteredParts();grid.innerHTML=results.map((p)=>`<article class="part-card"><button class="open-card" data-open="${p.id}" aria-label="${p.name}（${p.ja}）の詳細を開く"><div class="part-preview preview-${p.id}" aria-hidden="true"><span class="preview-label">${previewLabel(p)}</span>${previewMarkup(p)}<span class="preview-open">詳細を見る ${icon('arrow')}</span></div><div class="card-info"><div class="card-heading"><h3>${p.name}</h3>${icon('arrow')}</div><div class="ja-name">${p.ja}</div><p>${p.summary}</p><div class="card-foot"><span class="category-pill">${groups[p.category]}</span><span>${icon('library')} 公式実例 ${p.exampleIds.length}件</span></div></div></button><button class="save-button ${saved.has(p.id)?'saved':''}" data-save="${p.id}" aria-label="${p.name}を${saved.has(p.id)?'お気に入りから解除':'お気に入りに保存'}" aria-pressed="${saved.has(p.id)}">${icon('bookmark')}</button></article>`).join('');
document.querySelector('#result-count').textContent=`${results.length} 件`;document.querySelector('#saved-count').textContent=saved.size;document.querySelector('#collection-title').textContent=groups[filter];document.querySelector('#breadcrumb').textContent=groups[filter];document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});const empty=document.querySelector('#empty-state');empty.hidden=results.length>0;empty.querySelector('h3').textContent=filter==='saved'&&!search.value?'お気に入りを集めよう':'見つかりませんでした';empty.querySelector('p').textContent=filter==='saved'&&!search.value?'カード右上のブックマークから、気になるパーツを保存できます。':'別の名前や用途で検索してみてください。';applyView()}
function applyView(){grid.classList.toggle('list-view',view==='list');['grid','list'].forEach(v=>{const b=document.querySelector(`#${v}-view`);b.classList.toggle('selected',view===v);b.setAttribute('aria-pressed',String(view===v))})}
function toggleSaved(id){saved.has(id)?saved.delete(id):saved.add(id);const ok=persist('parts.favorites.v1',[...saved]);render();if(detail.open){const b=detail.querySelector('[data-detail-save]');b.classList.toggle('saved',saved.has(id));b.setAttribute('aria-pressed',String(saved.has(id)));b.setAttribute('aria-label',saved.has(id)?'お気に入りから解除':'お気に入りに保存')}notify(ok?(saved.has(id)?'お気に入りに保存しました':'お気に入りから解除しました'):'ブラウザーに保存できませんでした。この画面を閉じるまで保持します。')}
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render()}));
search.addEventListener('input',render);document.querySelector('#sort').addEventListener('change',render);
['grid','list'].forEach(v=>document.querySelector(`#${v}-view`).addEventListener('click',()=>{view=v;persist('parts.view.v1',view);applyView()}));
document.querySelector('#reset-filters').addEventListener('click',()=>{filter='all';search.value='';render();search.focus()});
grid.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;toggleSaved(id);grid.querySelector(`[data-save="${id}"]`)?.focus();return}const open=e.target.closest('[data-open]');if(open)openDetail(open.dataset.open)});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!detail.open&&!e.metaKey&&!e.ctrlKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}});
render();
document.querySelector('#collection-status').innerHTML='公式実例 '+examples.length+'件 <b>v0.2</b>';

function exampleFor(part) {
  return examples.find(example => example.id === part.featuredExampleId);
}

function previewMarkup(part) {
  const example = exampleFor(part);
  return example?.image
    ? `<img class="source-shot source-shot-${part.id}" src="${esc(example.image.path)}" alt="" loading="lazy" decoding="async">`
    : miniature(part.id);
}

function previewLabel(part) {
  const example = exampleFor(part);
  return example?.image ? `${esc(example.system)} · 公式実例` : '動作サンプル';
}

function exampleCards(part) {
  return examples.filter(example => example.partId === part.id).map(example => {
    const image = example.image;
    const coverage = example.verification.interactionCoverage;
    return `<article class="example-card">
      <div class="example-top"><span class="example-system">${esc(example.system)}</span><span>${example.kind === 'product-documentation' ? '製品の公式ガイド' : '公式サンプル'}</span></div>
      ${image ? `<a class="example-image-link" href="${esc(image.path)}" target="_blank" rel="noopener" aria-label="${esc(example.title)}の取得画像を拡大"><img class="example-image" src="${esc(image.path)}" alt="${esc(example.title)}。${esc(image.state)}" loading="lazy"></a><p class="capture-state">取得時の状態：${esc(image.state)}</p>` : ''}
      <h3>${esc(example.title)}</h3><p class="example-summary">${esc(example.summary)}</p>
      <ul class="example-features">${example.features.map(feature => `<li>${esc(feature)}</li>`).join('')}</ul>
      <div class="example-evidence"><span>出典確認 ${esc(example.checkedAt)}</span><span>${image ? '表示画像を取得済み' : '資料を確認済み'}</span></div>
      <p class="example-check-note">${coverage === 'trigger-or-tab-only' ? '開く操作・タブ切替の範囲を確認。その他の動作は未検証です。' : '実際の操作は未検証です。'}</p>
      <div class="example-links"><a href="${esc(example.url)}" target="_blank" rel="noopener noreferrer">公式ページで見る ${icon('external')}</a>${example.componentSourceUrl ? `<a href="${esc(example.componentSourceUrl)}" target="_blank" rel="noopener noreferrer">実装の参照先 ${icon('external')}</a>` : ''}</div>
    </article>`;
  }).join('');
}

function openDetail(id) {
  const part = parts.find(part => part.id === id);
  if (!part) return;
  currentId = id;
  detail.innerHTML = `<div class="detail-toolbar"><span>パーツ詳細 · ${String(parts.indexOf(part) + 1).padStart(2, '0')} / ${String(parts.length).padStart(2, '0')}</span><div><button class="icon-button ${saved.has(id) ? 'saved' : ''}" data-detail-save aria-pressed="${saved.has(id)}" aria-label="${saved.has(id) ? 'お気に入りから解除' : 'お気に入りに保存'}">${icon('bookmark')}</button><button class="icon-button" data-close aria-label="詳細を閉じる" autofocus>${icon('x')}</button></div></div>
    <div class="detail-body"><span class="detail-category">${groups[part.category]}</span><h2 id="detail-title">${esc(part.name)}</h2><div class="detail-ja">${esc(part.ja)}</div><p class="detail-description">${esc(part.description)}</p>
      <div class="detail-tabs" role="tablist" aria-label="パーツ詳細の内容">
        <button role="tab" id="tab-examples" aria-controls="panel-examples" aria-selected="true" data-tab="examples">公式実例 <span class="tab-count">${part.exampleIds.length}</span></button>
        <button role="tab" id="tab-demo" aria-controls="panel-demo" aria-selected="false" tabindex="-1" data-tab="demo">動作サンプル</button>
        <button role="tab" id="tab-notes" aria-controls="panel-notes" aria-selected="false" tabindex="-1" data-tab="notes">使い方・メモ</button>
      </div>
      <section role="tabpanel" id="panel-examples" aria-labelledby="tab-examples"><p class="examples-intro">公式サイトから集めた、${esc(part.ja)}の実例。</p>${exampleCards(part)}</section>
      <section role="tabpanel" id="panel-demo" aria-labelledby="tab-demo" hidden><p class="examples-intro">基本の動作を試すための、このライブラリ独自のサンプルです。</p><iframe class="demo-frame" title="${esc(part.name)} の動作サンプル" sandbox="allow-scripts"></iframe><p class="demo-caption">${esc(part.hint)}</p><div class="detail-section"><h3>こんなときに</h3><p>${esc(part.use)}</p></div><div class="detail-section"><h3>似たパーツとの違い</h3><p>${esc(part.difference)}</p></div></section>
      <section role="tabpanel" id="panel-notes" aria-labelledby="tab-notes" hidden><div class="detail-section"><h3>実装するときのポイント</h3><div class="recipe">${esc(part.recipe)}</div></div><div class="detail-section"><label for="part-notes"><h3>気に入ったところ・使いたい場面</h3></label><textarea id="part-notes" class="notes-area" maxlength="5000" placeholder="例：一覧を残したまま詳細を確認できる。予約管理の画面で使いたい。">${esc(typeof notes[id] === 'string' ? notes[id] : '')}</textarea><p class="notes-help">メモとお気に入りは、このブラウザーに保存されます。</p><button class="primary-button" data-save-notes>メモを保存</button></div></section>
      <div class="detail-section"><h3>こんな名前でも探せます</h3><div class="aliases">${part.aliases.slice(0, 4).map(alias => `<span>${esc(alias)}</span>`).join('')}</div></div><a class="reference-link" href="${esc(part.source)}" target="_blank" rel="noopener noreferrer"><span>辞書の参考資料 · ${esc(part.sourceName)}</span>${icon('external')}</a>
    </div>`;
  detail.querySelector('iframe').srcdoc = demoDocument(id);
  detail.querySelector('[data-close]').addEventListener('click', () => detail.close());
  detail.querySelector('[data-detail-save]').addEventListener('click', () => toggleSaved(id));
  detail.querySelector('[data-save-notes]').addEventListener('click', () => {
    notes[id] = detail.querySelector('#part-notes').value;
    notify(persist('parts.notes.v1', notes) ? 'メモを保存しました' : 'ブラウザーに保存できませんでした。この画面を閉じるまで保持します。');
  });
  const tabs = [...detail.querySelectorAll('[data-tab]')];
  const selectTab = selected => tabs.forEach(tab => {
    const active = tab === selected;
    tab.setAttribute('aria-selected', String(active));
    tab.tabIndex = active ? 0 : -1;
    detail.querySelector(`#panel-${tab.dataset.tab}`).hidden = !active;
  });
  tabs.forEach((tab, index) => {
    tab.addEventListener('click', () => selectTab(tab));
    tab.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
      selectTab(tabs[next]);
      tabs[next].focus();
    });
  });
  if (!detail.open) detail.showModal();
  detail.scrollTop = 0;
  document.body.style.overflow = 'hidden';
}

detail.addEventListener('click', event => {
  if (event.target !== detail) return;
  const bounds = detail.getBoundingClientRect();
  if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) detail.close();
});
detail.addEventListener('close', () => {
  document.body.style.overflow = '';
  grid.querySelector(`[data-open="${currentId}"]`)?.focus();
  currentId = null;
});

const demoCSS=`*{box-sizing:border-box}body{margin:0;padding:22px;font:14px/1.65 system-ui,'Noto Sans JP',sans-serif;color:#34425b;background:#f3f6fc}button,input{font:inherit}button{cursor:pointer;border:1px solid #dce3ef;border-radius:6px;background:white;color:#4c5c77;padding:8px 12px;line-height:1.5}button:hover{background:#edf2fc}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #7ca0ff;outline-offset:2px}.primary{background:#2457e8;color:white;border-color:#2457e8}.primary:hover{background:#1949ce}.muted{color:#8591a6;font-size:12px}.center{min-height:290px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:14px}.surface{background:white;border:1px solid #e0e7f1;border-radius:8px;padding:19px;width:100%}h2{font-size:18px;margin:0 0 8px}h3{font-size:15px;margin:0 0 10px}p{margin:8px 0 14px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.row{display:flex;justify-content:space-between;gap:10px;align-items:center}.badge{background:#e5f3ec;color:#387854;padding:3px 7px;font-size:11px;border-radius:15px}input[type=text],input[type=search]{width:100%;padding:9px 10px;border:1px solid #dce3ef;border-radius:5px;background:white;color:#3b4c67}input[type=checkbox]{accent-color:#2457e8;width:16px;height:16px}label{display:block;font-size:13px}dialog{border:1px solid #dce3ef;border-radius:9px;padding:22px;width:340px;max-width:calc(100% - 28px);color:#34425b;box-shadow:0 12px 40px #23375d24}dialog::backdrop{background:#21344d42}.close{padding:3px 8px;background:transparent;border:0;font-size:20px;line-height:1.2}.status{font-size:12px;color:#438169;min-height:20px}.demo-title{font-size:11px;letter-spacing:.4px;color:#96a3b8;position:absolute;top:9px;left:14px}.toast{position:fixed;bottom:20px;left:20px;right:20px;background:white;border:1px solid #bcdcca;border-radius:7px;padding:13px 15px;box-shadow:0 6px 25px #264c3315;display:flex;align-items:center;justify-content:space-between;font-size:13px;color:#3c7153}[hidden]{display:none!important}.drawer{position:fixed;right:0;top:0;bottom:0;width:min(245px,100%);padding:20px;background:white;border-left:1px solid #dce4ef;box-shadow:-8px 0 25px #30435e15}.drawer dl{font-size:13px}.drawer dt{color:#94a0b2;font-size:11px;margin-top:15px}.drawer dd{margin:3px 0}.reservation-row{width:100%;display:flex;justify-content:space-between;align-items:center;gap:8px;text-align:left;border:0;border-top:1px solid #edf0f5;border-radius:0;padding:13px 0}.reservation-row[aria-expanded=true]{color:#2457e8}.popover{margin:0;position:absolute;inset:auto;top:105px;left:50%;transform:translateX(-50%);padding:18px;width:245px;border:1px solid #d7e2da;border-radius:8px;background:white;box-shadow:0 8px 30px #243a2820}.popover label{display:flex;justify-content:space-between;align-items:center;margin-top:13px}.switch{appearance:none;width:32px!important;height:19px!important;border-radius:20px;background:#d2d9e6;position:relative;cursor:pointer}.switch:checked{background:#497e60}.switch:after{content:'';position:absolute;width:13px;height:13px;background:white;border-radius:50%;top:3px;left:3px;transition:left .15s}.switch:checked:after{left:16px}.commands{display:grid;gap:4px;margin-top:10px}.commands button{text-align:left;border:0;font-size:13px;padding:9px}.commands button.active{background:#edf2ff;color:#2457e8}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #e9edf4}th{font-size:11px;color:#8c99ac;font-weight:500}th button{font-size:11px;padding:0;border:0;color:#667998}td:first-child,th:first-child{padding-left:0}.table-wrap{overflow:auto}.tabs{display:flex;gap:21px;border-bottom:1px solid #e5eaf3;margin:14px 0 17px}.tabs button{border:0;border-radius:0;padding:8px 0;background:transparent;font-size:13px;color:#8894a7;border-bottom:2px solid transparent}.tabs button[aria-selected=true]{color:#2457e8;border-bottom-color:#2457e8}.tab-content{padding:15px;border:1px solid #e8ecf4;border-radius:6px;min-height:95px}.calendar{max-width:350px;margin:auto;background:white;border:1px solid #e0e5ef;border-radius:8px;padding:14px}.calendar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.calendar-head button{border:0;padding:2px 9px;font-size:18px}.calendar-head b{font-size:13px}.days{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}.days button{border:0;background:transparent;border-radius:4px;padding:3px 0;font-size:12px;min-height:27px}.days button:hover{background:#e8eefa}.days button.range{background:#e9effe;border-radius:0;color:#2457e8}.days button.edge{background:#2457e8;color:white}.weekday{text-align:center;font-size:10px;color:#9aabc1;padding-bottom:4px}.range-summary{font-size:11px;text-align:center;color:#54719d;line-height:1.6;margin:10px 0 0}.calendar input[type=date]{font:11px system-ui;min-width:0;width:100%;padding:4px 0;border:1px solid #e0e5ef;border-radius:3px}.date-inputs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px}.date-inputs label{font-size:10px;color:#8e9cb1}.help{font-size:11px;color:#8d9bb0;margin-top:8px}@media(max-width:350px){body{padding:16px}.surface{padding:13px}.tabs{gap:15px}.calendar{padding:10px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}`;
function demoContent(id){switch(id){
case'modal':return {html:`<div class="center"><div class="muted">MY COLLECTIONS</div><button class="primary" id="open">＋ コレクションを作成</button><div id="result" class="status" role="status"></div></div><dialog id="modal" aria-labelledby="title"><div class="row"><h2 id="title">コレクションを作成</h2><button class="close" id="close" aria-label="閉じる">×</button></div><p class="muted">お気に入りのパーツをまとめる場所。</p><form id="form"><label for="name">コレクション名</label><input id="name" type="text" placeholder="例：予約管理で使いたいUI" maxlength="50" required autofocus><div class="actions"><button type="button" id="cancel">キャンセル</button><button class="primary" type="submit">作成する</button></div></form></dialog>`,script:`const d=document.querySelector('#modal'),op=document.querySelector('#open');op.onclick=()=>d.showModal();document.querySelector('#close').onclick=document.querySelector('#cancel').onclick=()=>d.close();d.onclose=()=>op.focus();document.querySelector('#form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#name').value.trim();if(!name){document.querySelector('#name').setCustomValidity('コレクション名を入力してください');document.querySelector('#name').reportValidity();return}document.querySelector('#result').textContent='「'+name+'」を作成しました（デモ）';d.close()};document.querySelector('#name').oninput=e=>e.target.setCustomValidity('');`};
case'drawer':return {html:`<div class="surface" style="margin-top:18px"><h3>予約一覧</h3><div class="muted" style="margin-bottom:10px">3件の予約</div>${['田中 葵','佐藤 優希','鈴木 蓮'].map((n,i)=>`<button class="reservation-row" data-row="${i}" aria-expanded="false" aria-controls="drawer"><span>${n}</span><span class="badge">確定</span><span>›</span></button>`).join('')}</div><section class="drawer" id="drawer" role="region" aria-label="予約詳細" hidden><div class="row"><h3>予約詳細</h3><button class="close" id="close" aria-label="予約詳細を閉じる">×</button></div><dl><dt>ゲスト</dt><dd id="guest"></dd><dt>宿泊期間</dt><dd>2026.09.18 – 09.20</dd><dt>部屋タイプ</dt><dd>スタンダードツイン</dd><dt>ステータス</dt><dd><span class="badge">予約確定</span></dd></dl></section>`,script:`let origin;const d=document.querySelector('#drawer'),rows=[...document.querySelectorAll('[data-row]')];rows.forEach(b=>b.onclick=()=>{origin=b;rows.forEach(r=>r.setAttribute('aria-expanded',String(r===b)));document.querySelector('#guest').textContent=['田中 葵','佐藤 優希','鈴木 蓮'][b.dataset.row];d.hidden=false;document.querySelector('#close').focus()});const close=()=>{d.hidden=true;rows.forEach(r=>r.setAttribute('aria-expanded','false'));origin?.focus()};document.querySelector('#close').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!d.hidden)close()});`};
case'popover':return {html:`<div class="center" style="justify-content:flex-start;padding-top:34px"><button id="trigger" popovertarget="settings">☷ 表示設定</button><div class="surface" id="preview" style="max-width:285px;margin-top:12px"><div id="label">Parts library</div><p class="muted" id="description">見つけたUIを、次の画面づくりへ。</p></div></div><div popover id="settings" class="popover"><h3>表示設定</h3><label>タイトルを表示<input class="switch" type="checkbox" id="toggle-label" checked></label><label>説明を表示<input class="switch" type="checkbox" id="toggle-description" checked></label></div>`,script:`document.querySelector('#toggle-label').onchange=e=>document.querySelector('#label').hidden=!e.target.checked;document.querySelector('#toggle-description').onchange=e=>document.querySelector('#description').hidden=!e.target.checked;`};
case'command':return {html:`<div class="center"><button class="primary" id="open">⌘ コマンドを開く</button><div class="status" id="result" role="status"></div></div><dialog id="commands" aria-label="コマンドパレット"><div class="row" style="margin-bottom:10px"><label for="query">操作を検索</label><button class="close" id="close" aria-label="閉じる">×</button></div><input type="search" id="query" placeholder="例：作成、パーツ、設定" autocomplete="off" autofocus><div class="commands" id="options"></div><div class="help">↑↓ で選択 · Enter で実行 · Esc で閉じる</div></dialog>`,script:`const d=document.querySelector('#commands'),q=document.querySelector('#query'),out=document.querySelector('#options'),items=[{title:'コレクションを作成',aliases:'新規追加 collection create'},{title:'パーツ一覧を開く',aliases:'部品 閲覧 browse'},{title:'表示設定を開く',aliases:'設定 settings'}];let active=0,results=[];function draw(){results=items.filter(i=>(i.title+' '+i.aliases).toLowerCase().includes(q.value.trim().toLowerCase()));active=Math.min(active,Math.max(0,results.length-1));out.innerHTML=results.length?results.map((r,i)=>'<button type="button" class="'+(i===active?'active':'')+'" data-index="'+i+'">'+r.title+'</button>').join(''):'<p class="muted" role="status">該当する操作がありません</p>';out.querySelectorAll('button').forEach(b=>b.onclick=()=>run(Number(b.dataset.index)))}function run(i){if(!results[i])return;document.querySelector('#result').textContent='「'+results[i].title+'」を実行しました（デモ）';d.close()}document.querySelector('#open').onclick=()=>{q.value='';active=0;draw();d.showModal()};document.querySelector('#close').onclick=()=>d.close();d.onclose=()=>document.querySelector('#open').focus();q.oninput=()=>{active=0;draw()};q.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();run(active)}else if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+results.length)%Math.max(1,results.length);draw()}};draw();`};
case'table':return {html:`<div class="surface" style="margin-top:18px"><div class="row"><h3>予約一覧</h3><span class="muted" id="selected" role="status">0件選択</span></div><div class="table-wrap"><table><caption style="text-align:left;font-size:11px;color:#8493a9;padding:2px 0 8px">2026年9月の予約（サンプル）</caption><thead><tr><th><input type="checkbox" id="all" aria-label="すべての予約を選択"></th><th scope="col">ゲスト</th><th scope="col">状態</th><th scope="col" id="amount-heading" aria-sort="none"><button id="sort">金額 ↕</button></th></tr></thead><tbody id="rows"></tbody></table></div></div>`,script:`const data=[{id:0,name:'田中 葵',amount:24000},{id:1,name:'佐藤 優希',amount:18500},{id:2,name:'鈴木 蓮',amount:32000}],checked=new Set();let direction=0;function state(){document.querySelector('#selected').textContent=checked.size+'件選択';document.querySelector('#all').checked=checked.size===data.length;document.querySelector('#all').indeterminate=checked.size>0&&checked.size<data.length}function draw(){document.querySelector('#rows').innerHTML=[...data].sort((a,b)=>direction*(a.amount-b.amount)).map(r=>'<tr><td><input type="checkbox" data-id="'+r.id+'" aria-label="'+r.name+'の予約を選択" '+(checked.has(r.id)?'checked':'')+'></td><td>'+r.name+'</td><td><span class="badge">確定</span></td><td>¥'+r.amount.toLocaleString('ja-JP')+'</td></tr>').join('');document.querySelectorAll('[data-id]').forEach(c=>c.onchange=()=>{c.checked?checked.add(Number(c.dataset.id)):checked.delete(Number(c.dataset.id));state()});state()}document.querySelector('#sort').onclick=()=>{direction=direction===1?-1:1;document.querySelector('#amount-heading').setAttribute('aria-sort',direction===1?'ascending':'descending');document.querySelector('#sort').textContent='金額 '+(direction===1?'↑':'↓');draw()};document.querySelector('#all').onchange=e=>{data.forEach(r=>e.target.checked?checked.add(r.id):checked.delete(r.id));draw()};draw();`};
case'tabs':return {html:`<div class="surface" style="margin-top:25px"><h3>プロジェクト設定</h3><div class="tabs" role="tablist" aria-label="プロジェクト情報">${['基本情報','メンバー','履歴'].map((n,i)=>`<button role="tab" id="t${i}" aria-controls="p${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${n}</button>`).join('')}</div><section class="tab-content" id="p0" role="tabpanel" aria-labelledby="t0" tabindex="0"><strong>Parts library</strong><p class="muted">気になるUIを集めるワークスペース。</p></section><section class="tab-content" id="p1" role="tabpanel" aria-labelledby="t1" tabindex="0" hidden><strong>1名のメンバー</strong><p class="muted">あなた · オーナー</p></section><section class="tab-content" id="p2" role="tabpanel" aria-labelledby="t2" tabindex="0" hidden><strong>最近のアクティビティ</strong><p class="muted">9月15日 · ライブラリを作成</p></section></div>`,script:`const tabs=[...document.querySelectorAll('[role=tab]')];function select(i){tabs.forEach((t,j)=>{t.setAttribute('aria-selected',String(i===j));t.tabIndex=i===j?0:-1;document.querySelector('#p'+j).hidden=i!==j})}tabs.forEach((t,i)=>{t.onclick=()=>select(i);t.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;select(next);tabs[next].focus()}});`};
case'toast':return {html:`<div class="center"><div class="muted">COLLECTION SETTINGS</div><button class="primary" id="save">変更を保存</button><span class="muted">通知が出ても、そのまま作業できます。</span></div><div class="toast" id="toast" hidden><span id="announcement" role="status" aria-live="polite"></span><button class="close" id="close" aria-label="通知を閉じる">×</button></div>`,script:`let timer,remaining=6000,started;const toast=document.querySelector('#toast');const pause=()=>{clearTimeout(timer);if(started){remaining=Math.max(0,remaining-(Date.now()-started));started=null}};const resume=()=>{if(toast.hidden||toast.matches(':hover')||toast.contains(document.activeElement))return;clearTimeout(timer);started=Date.now();timer=setTimeout(hide,remaining)};function hide(){clearTimeout(timer);toast.hidden=true;started=null}document.querySelector('#save').onclick=()=>{clearTimeout(timer);remaining=6000;toast.hidden=false;document.querySelector('#announcement').textContent='✓ 変更を保存しました';resume()};document.querySelector('#close').onclick=()=>{hide();document.querySelector('#save').focus()};toast.onmouseenter=pause;toast.onmouseleave=resume;toast.onfocusin=pause;toast.onfocusout=()=>setTimeout(resume,0);`};
case'date':return {html:`<div class="calendar"><div class="date-inputs"><label for="start">開始日<input type="date" id="start" value="2026-09-18"></label><label for="end">終了日<input type="date" id="end" value="2026-09-22"></label></div><div class="calendar-head"><button id="previous" aria-label="前の月">‹</button><b id="month"></b><button id="next" aria-label="次の月">›</button></div><div class="days" id="days" role="group" aria-label="日付を選択"></div><p class="range-summary" id="summary" role="status"></p></div>`,script:`let year=2026,month=8,start='2026-09-18',end='2026-09-22';const pad=n=>String(n).padStart(2,'0'),key=d=>year+'-'+pad(month+1)+'-'+pad(d),valid=v=>/^\\d{4}-\\d{2}-\\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v));function draw(){document.querySelector('#month').textContent=year+'年 '+(month+1)+'月';const offset=(new Date(year,month,1).getDay()+6)%7,count=new Date(year,month+1,0).getDate();document.querySelector('#days').innerHTML=['月','火','水','木','金','土','日'].map(d=>'<span class="weekday">'+d+'</span>').join('')+'<span></span>'.repeat(offset)+Array.from({length:count},(_,i)=>{const k=key(i+1),edge=k===start||k===end,range=start&&end&&k>start&&k<end;return '<button data-date="'+k+'" aria-label="'+k+(k===start?' 開始日':k===end?' 終了日':'')+'" aria-pressed="'+(edge||!!range)+'" class="'+(edge?'edge':range?'range':'')+'">'+(i+1)+'</button>'}).join('');document.querySelector('#start').value=start;document.querySelector('#end').value=end;document.querySelector('#end').min=start;document.querySelector('#summary').textContent=start&&end?start+' → '+end+' · '+Math.round((Date.parse(end)-Date.parse(start))/86400000)+'泊':start?'終了日を選んでください':'開始日を選んでください';document.querySelectorAll('[data-date]').forEach(b=>{b.onclick=()=>{const v=b.dataset.date;if(!start||end){start=v;end=''}else if(v<start){end=start;start=v}else end=v;draw();document.querySelector('[data-date="'+v+'"]').focus()};b.onkeydown=e=>{const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(!(e.key in offsets))return;e.preventDefault();const d=new Date(b.dataset.date+'T12:00:00');d.setDate(d.getDate()+offsets[e.key]);year=d.getFullYear();month=d.getMonth();draw();document.querySelector('[data-date="'+key(d.getDate())+'"]').focus()}})}document.querySelector('#previous').onclick=()=>{month--;if(month<0){month=11;year--}draw()};document.querySelector('#next').onclick=()=>{month++;if(month>11){month=0;year++}draw()};document.querySelector('#start').onchange=e=>{if(!valid(e.target.value))return;start=e.target.value;if(end<start)end='';year=Number(start.slice(0,4));month=Number(start.slice(5,7))-1;draw()};document.querySelector('#end').onchange=e=>{if(!valid(e.target.value))return;if(start&&e.target.value<start){e.target.setCustomValidity('開始日以降の日付を選んでください');e.target.reportValidity();return}e.target.setCustomValidity('');end=e.target.value;if(!start)start=end;year=Number(end.slice(0,4));month=Number(end.slice(5,7))-1;draw()};document.querySelector('#end').oninput=e=>e.target.setCustomValidity('');draw();`};
default:throw new Error('Unknown demo');
}}
function demoDocument(id){const d=demoContent(id);return `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(parts.find(p=>p.id===id).name)} 動作サンプル</title><style>${demoCSS}</style></head><body>${d.html}<script>${d.script}<\/script></body></html>`}

// Optional WebMCP: the same search and detail actions used by the visible interface.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
register({name:'search_ui_parts',description:'Search the sample UI library and update the visible collection. Returns matching component IDs and names.',inputSchema:{type:'object',properties:{query:{type:'string'},category:{type:'string',enum:Object.keys(groups)}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>500||input.category!==undefined&&!Object.hasOwn(groups,input.category))throw new Error('Invalid search input');search.value=input.query;filter=input.category||'all';render();return {results:filteredParts().map(p=>({id:p.id,name:p.name,ja:p.ja}))}}});
register({name:'open_ui_part',description:'Open a component detail panel and its interactive sample. Does not save or change the component.',inputSchema:{type:'object',properties:{id:{type:'string',enum:parts.map(p=>p.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!parts.some(p=>p.id===input.id))throw new Error('Unknown component');openDetail(input.id);return {id:input.id,opened:true}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
